mapper.sql:
FROM community_comment c JOIN cms_news n ON n.id = c.news_id WHERE c.is_deleted = 0 AND n.is_deleted = 0
AND c.ai_status = #{status}
AND c.ai_verdict = #{verdict}
AND c.is_hidden = #{hidden}
AND ( LOCATE(#{keyword}, c.content) > 0 OR EXISTS ( SELECT 1 FROM user_profile p WHERE p.user_id = c.user_id AND p.is_deleted = 0 AND LOCATE(#{keyword}, p.nickname) > 0 ) )
